            )
        }

        return try {
            val svc = context.getSystemService(Context.GAME_SERVICE) ?: return reflectFail()
            val method = svc.javaClass.methods.firstOrNull { m ->
                m.name == "setGameMode" && m.parameterCount == 2
            } ?: return reflectFail()
            val mode = gameModePerformance() ?: return reflectFail()
            method.invoke(svc, pkg, mode)
            Outcome(true, "Игровой режим", "Производительный режим запрошен для $pkg")
        } catch (t: Throwable) {
            reflectFail(t.javaClass.simpleName)
        }
    }

    private fun reflectFail(reason: String = "API недоступен") =
        Outcome(false, "Игровой режим", "Не удалось: $reason. Нужны права shell (Shizuku) или Android 12+")

    // ------------------------------------------------- 6. Фоновые процессы

    /**
     * Освобождает ресурсы: фоновые приложения занимают ядра и память,
     * из-за чего страдают и кадры, и аудиобуфер.
     */
    fun killHeavyBackground(): Outcome {
        val heavy = listOf(
            "org.telegram.messenger", "com.discord", "com.zhiliaoapp.musically",
            "com.google.android.youtube", "com.spotify.music", "com.facebook.katana",
            "com.instagram.android", "com.android.chrome", "com.linkedin.android",
            "com.netflix.mediaclient", "com.booking", "com.uber.driver",
            "com.snapchat.android", "com.twitter.android", "com.whatsapp"
        )
        val me = context.packageName
        var killed = 0
        var blocked = 0
        for (p in heavy) {
            if (p == me) continue
            try {
                activityManager.killBackgroundProcesses(p)
                killed++
            } catch (_: SecurityException) {
                blocked++
            } catch (_: Throwable) {
                blocked++
            }
        }
        return if (killed > 0) {
            Outcome(
                true,
                "Фоновые процессы",
                "Освобождено пакетов: $killed" + if (blocked > 0) ", системных пропущено: $blocked" else ""
            )
        } else {
            Outcome(false, "Фоновые процессы", "Ни один процесс не завершён (нужно разрешение или нет прав)")
        }
    }

    // ------------------------------------------------- Диагностика

    /**
     * Запрашивает у системы сведения о текущем маршруте. Используется для
     * подтверждения, что переключение Bluetooth реально произошло.
     */
    fun currentOutputDeviceName(): String? = try {
        val res = Privileged.runner().run(listOf("dumpsys", "audio"), 4000)
        Regex("Current:\\s*\\d+\\s*\\(([^)]+)\\)").find(res.stdout)?.groupValues?.get(1)
    } catch (_: Throwable) {
        null
    }

    fun dndEnabled(): Boolean = try {
        notificationManager.currentInterruptionFilter != NotificationManager.INTERRUPTION_FILTER_ALL
    } catch (_: Throwable) {
        false
    }

    fun animationsDisabled(): Boolean = try {
        Settings.Global.getFloat(context.contentResolver, Settings.Global.ANIMATOR_DURATION_SCALE, 1f) == 0f
    } catch (_: Throwable) {
        false
    }

    private companion object {
        /**
         * Значение BluetoothAdapter.ACTION_REQUEST_DISABLE. Константа скрыта
         * в публичных стабах SDK, поэтому берём документированное значение строки.
         */
        const val ACTION_REQUEST_DISABLE = "android.bluetooth.adapter.action.REQUEST_DISABLE"

        /** android.app.GameManager.MODE_PERFORMANCE, прочитанная рефлексией. */
        fun gameModePerformance(): Int? = try {
            Class.forName("android.app.GameManager")
                .getField("MODE_PERFORMANCE")
                .get(null) as? Int
        } catch (_: Throwable) {
            null
        }
    }
}

