fun setMicDenoise(enable: Boolean): Outcome {
    val ns = toggleEffect(
        enable = enable,
        create = { if (NoiseSuppressor.isAvailable()) NoiseSuppressor.create(SESSION) else null },
        set = { it.enabled = enable },
        read = { NoiseSuppressor.create(SESSION)?.enabled }
    )
    val aec = toggleEffect(
        enable = enable,
        create = { if (AcousticEchoCanceler.isAvailable()) AcousticEchoCanceler.create(SESSION) else null },
        set = { it.enabled = enable },
        read = { AcousticEchoCanceler.create(SESSION)?.enabled }
    )
    val gain = toggleEffect(
        enable = enable,
        create = { if (AutomaticGainControl.isAvailable()) AutomaticGainControl.create(SESSION) else null },
        set = { it.enabled = enable },
        read = { AutomaticGainControl.create(SESSION)?.enabled }
    )

    val applied = listOf(ns, aec, gain).count { it }
    val available = listOf(
        NoiseSuppressor.isAvailable(),
        AcousticEchoCanceler.isAvailable(),
        AutomaticGainControl.isAvailable()
    ).count { it }
    val verb = if (enable) "включены" else "выключены"

    return when {
        available == 0 ->
            Outcome(false, "Микрофон", "Аудиопроцессор на этой прошивке не поддерживает эти эффекты")
        applied == 0 ->
            Outcome(
                false,
                "Микрофон",
                "Сессия микрофона сейчас не активна: эффекты $verb только там, где игра или " +
                    "мессенджер держат свою сессию. Запустите голосовой чат — состояние обновится",
                manual = true
            )
        else ->
            Outcome(
                applied == available,
                "Микрофон",
                "Обработка $verb: эффектов затронуто $applied из $available"
            )
    }
